			}
			if err != nil || !parallelMode || result.Outcome != greenhouse.Running && result.Outcome != greenhouse.Paused {
				break
			}
			if time.Until(deadline) <= 0 {
				break
			}
			timer := time.NewTimer(time.Second)
			select {
